css:
@import url("https://fonts.googleapis.com/css2?family=Albert+Sans:wght@400;500;600;700;800&display=swap");
:root{--sage:#5B7B65;--sage-l:#E9F0EA;--forest:#1F2E25;--sun:#F2B544;--text:#24302A;--muted:#66736B;--line:#DDE5DE;--bg:#F7F9F7;
--font:"Albert Sans",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1200px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);font-size:17px;line-height:1.6;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{margin:0;line-height:1.05;color:var(--forest);letter-spacing:-.025em;font-weight:800}h3{font-weight:700}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--sun);padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--sun);outline-offset:3px;border-radius:6px}
.site-header{border-bottom:1px solid var(--line);background:#fff;position:sticky;top:0;z-index:40}
.nav{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font-weight:800;font-size:22px;text-decoration:none;color:var(--forest);letter-spacing:-.02em}.logo span{color:var(--sage)}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:600}.menu a:hover{color:var(--sage)}
.cart{background:var(--forest);color:#fff;border-radius:999px;padding:8px 16px;font-weight:700;text-decoration:none;font-size:15px}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:8px;padding:8px 10px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:var(--forest);margin:4px 0}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:15px 26px;border-radius:999px;font-weight:700;text-decoration:none;border:2px solid transparent;font-family:var(--font);font-size:17px;cursor:pointer}
.btn-f{background:var(--forest);color:#fff}.btn-f:hover{background:var(--sage)}
.prod{padding:40px 0 80px}
.prod-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:56px;align-items:start}
.gal{position:sticky;top:90px}
.main-img{background:var(--sage-l);border-radius:24px;overflow:hidden;aspect-ratio:1/1}
.main-img img{width:100%;height:100%;object-fit:cover;transition:filter .3s}
.thumbs{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:10px}
.thumbs button{border:2px solid transparent;border-radius:14px;overflow:hidden;padding:0;cursor:pointer;background:var(--sage-l);aspect-ratio:1/1}
.thumbs button[aria-pressed="true"]{border-color:var(--forest)}
.thumbs img{width:100%;height:100%;object-fit:cover}
.info .rt{display:flex;align-items:center;gap:8px;font-size:15px;color:var(--muted)}.info .rt b{color:var(--sun);letter-spacing:2px}
.info h1{font-size:clamp(36px,4.4vw,56px);margin:10px 0}
.info .lead{font-size:19px;color:var(--muted)}
.price{font-size:34px;font-weight:800;color:var(--forest);margin:18px 0}.price small{font-size:16px;font-weight:500;color:var(--muted);margin-left:8px}
.opt{margin:20px 0}
.opt .lab{font-weight:700;margin-bottom:10px;display:block}.opt .lab span{font-weight:500;color:var(--muted)}
.swatches{display:flex;gap:10px}
.swatches button{width:42px;height:42px;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 1px var(--line);cursor:pointer}
.swatches button[aria-pressed="true"]{box-shadow:0 0 0 2px var(--forest)}
.sizes{display:flex;gap:10px;flex-wrap:wrap}
.sizes button{border:1.5px solid var(--line);background:#fff;border-radius:12px;padding:10px 18px;font:inherit;font-weight:700;cursor:pointer}
.sizes button[aria-pressed="true"]{border-color:var(--forest);background:var(--sage-l)}
.buy{display:flex;gap:12px;margin:24px 0 14px}
.qty{display:flex;align-items:center;border:1.5px solid var(--line);border-radius:999px}
.qty button{width:44px;height:52px;border:0;background:none;font-size:20px;cursor:pointer}.qty span{min-width:28px;text-align:center;font-weight:700}
.buy .btn{flex:1}
.ship{display:grid;gap:8px;font-size:15px;color:var(--muted);margin-top:16px;padding:16px;background:var(--bg);border-radius:16px}
.ship b{color:var(--forest)}
.acc details{border-bottom:1px solid var(--line);padding:16px 0}
.acc summary{cursor:pointer;font-weight:700;list-style:none;display:flex;justify-content:space-between}.acc summary::-webkit-details-marker{display:none}.acc summary::after{content:"+"}.acc details[open] summary::after{content:"−"}
.acc p{margin:10px 0 0;color:var(--muted);font-size:16px}
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,120px);background:var(--forest);color:#fff;padding:14px 22px;border-radius:999px;font-weight:600;transition:transform .3s;z-index:70}
.toast.show{transform:translate(-50%,0)}
.feat{background:var(--forest);color:#C9D6CD}
.feat h2{color:#fff}
section{padding:90px 0}
.head{text-align:center;max-width:700px;margin:0 auto 50px}.head h2{font-size:clamp(34px,4.6vw,58px)}.head p{color:var(--muted);font-size:19px;margin-top:14px}
.feat .head p{color:#A9BBAE}
.f-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.f-card{background:#2A3D31;border-radius:20px;padding:26px}
.f-card b{font-size:40px;font-weight:800;color:var(--sun);display:block;line-height:1}
.f-card h3{color:#fff;font-size:19px;margin:12px 0 6px}.f-card p{margin:0;font-size:15px}
.temp{max-width:760px;margin:50px auto 0}
.tb{display:grid;grid-template-columns:150px 1fr 60px;gap:12px;align-items:center;margin-bottom:12px;font-weight:600;color:#fff}
.tb .t{height:18px;background:#2A3D31;border-radius:9px;overflow:hidden}.tb .t i{display:block;height:100%;border-radius:9px}
.calc{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}
.calc img{border-radius:24px;aspect-ratio:4/3;object-fit:cover;width:100%}
.calc h2{font-size:clamp(32px,4vw,50px);margin-bottom:14px}
.calc label{font-weight:700;display:block;margin:20px 0 8px}
.calc input[type=range]{width:100%;accent-color:var(--sage)}
.res{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:20px}
.res div{background:var(--sage-l);border-radius:16px;padding:18px}.res b{font-size:34px;font-weight:800;color:var(--forest);display:block;line-height:1.1}.res span{font-size:15px;color:var(--muted)}
.reviews{background:var(--bg)}
.rv-top{display:grid;grid-template-columns:300px 1fr;gap:40px;align-items:start}
.score b{font-size:64px;font-weight:800;color:var(--forest);line-height:1}.score .st{color:var(--sun);letter-spacing:3px;font-size:20px}
.dist .r{display:grid;grid-template-columns:40px 1fr 40px;gap:10px;align-items:center;font-size:14px;margin:6px 0}
.dist .t{height:8px;background:#E2E8E3;border-radius:4px;overflow:hidden}.dist .t i{display:block;height:100%;background:var(--sun)}
.rv-list{display:grid;gap:14px}
.rv{background:#fff;border-radius:18px;padding:22px;margin:0;border:1px solid var(--line)}
.rv .st{color:var(--sun);letter-spacing:2px}.rv p{margin:8px 0}.rv cite{font-style:normal;font-size:14px;color:var(--muted)}
.faq{max-width:800px;margin:0 auto}
.faq details{border-bottom:1px solid var(--line);padding:18px 0}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:19px;display:flex;justify-content:space-between;gap:16px;color:var(--forest)}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";color:var(--sage);font-size:24px;line-height:1}.faq details[open] summary::after{content:"−"}
.faq details p{margin:10px 0 0;color:var(--muted)}
.sticky{position:fixed;left:0;right:0;bottom:0;background:#fff;border-top:1px solid var(--line);padding:12px 22px;display:flex;align-items:center;justify-content:space-between;gap:14px;z-index:50;transform:translateY(100%);transition:transform .3s}
.sticky.show{transform:none}
.sticky img{width:48px;height:48px;border-radius:10px;object-fit:cover}
.sticky .pi{display:flex;gap:12px;align-items:center}.sticky b{display:block}.sticky small{color:var(--muted)}
footer{padding:40px 0 100px;color:var(--muted);font-size:15px;border-top:1px solid var(--line)}
.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}
footer ul{list-style:none;padding:0;margin:0;display:flex;gap:20px;flex-wrap:wrap}footer a{text-decoration:none}footer a:hover{color:var(--forest)}
@media (max-width:980px){.menu{display:none}.burger{display:block}.menu.open{display:flex;flex-direction:column;position:absolute;top:68px;left:0;right:0;background:#fff;padding:20px;border-bottom:1px solid var(--line);gap:14px}
.prod-grid,.calc,.rv-top{grid-template-columns:1fr}.gal{position:static}.f-grid{grid-template-columns:1fr 1fr}}
@media (max-width:560px){section{padding:64px 0}.f-grid,.res{grid-template-columns:1fr}.tb{grid-template-columns:100px 1fr 50px}.sticky .pi small{display:none}.cart{display:none}}

.toast{visibility:hidden}.toast.show{visibility:visible}

javascript:
const $=id=>document.getElementById(id);let col='Sage',filt='none',price=34,size='750 ml',q=1,cart=0;
function upd(){$('price').textContent='$'+price;$('stPrice').textContent='$'+price*q;$('stInfo').textContent=col+' · '+size;$('colName').textContent=col;$('mainImg').style.filter=filt;$('stImg').style.filter=filt;$('qn').textContent=q}
$('sw').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#sw button').forEach(x=>x.setAttribute('aria-pressed',x===b));col=b.dataset.n;filt=b.dataset.f;
 document.querySelector('.thumbs [data-src="1602143407151-7111542de6e8"]').click();upd()});
$('sz').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#sz button').forEach(x=>x.setAttribute('aria-pressed',x===b));price=+b.dataset.p;size=b.textContent;upd()});
document.querySelectorAll('.thumbs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.thumbs button').forEach(x=>x.setAttribute('aria-pressed',x===b));const m=$('mainImg');m.src=`https://images.unsplash.com/photo-${b.dataset.src}?w=1000&q=80&auto=format&fit=crop`;m.alt=b.dataset.alt;m.style.filter=b.dataset.src==='1602143407151-7111542de6e8'?filt:'none'}));
$('qm').addEventListener('click',()=>{q=Math.max(1,q-1);upd()});$('qp').addEventListener('click',()=>{q++;upd()});
function add(){cart+=q;$('cc').textContent=cart;const t=$('toast');t.textContent=`Added ${q} × Everbottle (${col}, ${size}) to cart`;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
$('add').addEventListener('click',add);$('add2').addEventListener('click',add);
new IntersectionObserver(([en])=>{const s=$('sticky');s.classList.toggle('show',!en.isIntersecting&&en.boundingClientRect.top<0);s.setAttribute('aria-hidden',en.isIntersecting)}).observe($('add'));
function calc(){const b=+$('bpw').value;$('bv').textContent=b;$('saved').textContent=(b*52).toLocaleString();$('money').textContent='$'+Math.round(b*52*1.5).toLocaleString()}$('bpw').addEventListener('input',calc);calc();upd();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
